ON CONFLICT (COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid),
               COALESCE(global_species_key, '~'), name)
    DO UPDATE SET
        origin                  = COALESCE(EXCLUDED.origin, breeds.origin),
        use_kind                = COALESCE(EXCLUDED.use_kind, breeds.use_kind),
        source                  = EXCLUDED.source,
        source_ref              = EXCLUDED.source_ref,
        birth_weight_kg         = COALESCE(EXCLUDED.birth_weight_kg, breeds.birth_weight_kg),
        mature_weight_kg        = COALESCE(EXCLUDED.mature_weight_kg, breeds.mature_weight_kg),
        eggs_per_year           = COALESCE(EXCLUDED.eggs_per_year, breeds.eggs_per_year),
        egg_production_strain   = COALESCE(EXCLUDED.egg_production_strain, breeds.egg_production_strain),
        wool_kg_per_year        = COALESCE(EXCLUDED.wool_kg_per_year, breeds.wool_kg_per_year),
        wool_micron_min         = COALESCE(EXCLUDED.wool_micron_min, breeds.wool_micron_min),
        wool_micron_max         = COALESCE(EXCLUDED.wool_micron_max, breeds.wool_micron_max),
        gestation_days          = COALESCE(EXCLUDED.gestation_days, breeds.gestation_days),
        litter_size             = COALESCE(EXCLUDED.litter_size, breeds.litter_size),
        global_species_key      = COALESCE(EXCLUDED.global_species_key, breeds.global_species_key);

-- Correct the origins that the initial migration got wrong. `DO NOTHING` above
-- would otherwise keep the stub rows forever, so these two facts are stated
-- rather than silently inherited.
UPDATE breeds SET origin = 'Australia'
    WHERE species = 'Sheep' AND name = 'Merino' AND origin IS DISTINCT FROM 'Australia';
UPDATE breeds SET origin = 'Egypt'
    WHERE name IN ('Nubian', 'Anglo-Nubian') AND name = 'Nubian'
      AND origin IS DISTINCT FROM 'Egypt';

COMMIT;
